package dev.eugheist.ttmodern;
final class FumeToolAudit {
 static void run(net.minecraft.server.level.ServerLevel world,net.minecraft.core.BlockPos at){
  var registry=world.registryAccess().registryOrThrow(dan200.computercraft.api.turtle.ITurtleUpgrade.REGISTRY);var holder=registry.getHolderOrThrow(dan200.computercraft.api.turtle.ITurtleUpgrade.createKey(net.minecraft.resources.ResourceLocation.parse("ttinkerer:fume_tool")));if(!(holder.value() instanceof FumeTool upgrade)||!upgrade.getCraftingItem().is(ThaumicTinkererModern.GAS_REMOVER.get())||upgrade.getUpgradeType()!=dan200.computercraft.api.turtle.TurtleUpgradeType.TOOL)throw new IllegalStateException("Fume loaded upgrade/type/crafting item");
  var positions=java.util.List.of(at.offset(-3,-3,-3),at.offset(2,2,2),at.offset(3,0,0),at.offset(0,1,0),at.offset(0,2,0));var backup=new java.util.LinkedHashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();for(var p:positions){if(world.getBlockEntity(p)!=null)throw new IllegalStateException("Fume fixture block entity collision");backup.put(p,world.getBlockState(p));}
  dan200.computercraft.shared.turtle.blocks.TurtleBlockEntity turtle=null;
  try{
   var block=net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("computercraft:turtle_normal"));world.setBlock(at,block.defaultBlockState(),3);turtle=(dan200.computercraft.shared.turtle.blocks.TurtleBlockEntity)world.getBlockEntity(at);var access=turtle.getAccess();access.setUpgrade(dan200.computercraft.api.turtle.TurtleSide.LEFT,dan200.computercraft.api.upgrades.UpgradeData.ofDefault(holder));access.setFuelLevel(37);access.getInventory().setItem(0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,3));
   world.setBlock(positions.get(0),ThaumicTinkererModern.LIGHT_GAS.get().defaultBlockState(),3);world.setBlock(positions.get(1),ThaumicTinkererModern.SHADOW_GAS.get().defaultBlockState(),3);world.setBlock(positions.get(2),ThaumicTinkererModern.LIGHT_GAS.get().defaultBlockState(),3);world.setBlock(positions.get(3),ThaumicTinkererModern.NITOR_LIGHT.get().defaultBlockState(),3);world.setBlock(positions.get(4),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);
   if(upgrade.useTool(access,dan200.computercraft.api.turtle.TurtleSide.LEFT,dan200.computercraft.api.turtle.TurtleVerb.ATTACK,net.minecraft.core.Direction.UP).isSuccess()||!world.getBlockState(positions.get(0)).is(ThaumicTinkererModern.LIGHT_GAS.get()))throw new IllegalStateException("Fume attack must fail without removal");
   if(!upgrade.useTool(access,dan200.computercraft.api.turtle.TurtleSide.LEFT,dan200.computercraft.api.turtle.TurtleVerb.DIG,net.minecraft.core.Direction.DOWN).isSuccess()||!world.getBlockState(positions.get(0)).isAir()||!world.getBlockState(positions.get(1)).isAir()||!world.getBlockState(positions.get(3)).isAir()||!world.getBlockState(positions.get(2)).is(ThaumicTinkererModern.LIGHT_GAS.get())||!world.getBlockState(positions.get(4)).is(net.minecraft.world.level.block.Blocks.STONE))throw new IllegalStateException("Fume original asymmetrical bounds/gas only");
   if(access.getFuelLevel()!=37||access.getInventory().getItem(0).getCount()!=3||upgrade.createPeripheral(access,dan200.computercraft.api.turtle.TurtleSide.LEFT)!=null||!upgrade.useTool(access,dan200.computercraft.api.turtle.TurtleSide.LEFT,dan200.computercraft.api.turtle.TurtleVerb.DIG,net.minecraft.core.Direction.NORTH).isSuccess())throw new IllegalStateException("Fume fuel/inventory/no peripheral/empty success");
   var saved=turtle.saveWithFullMetadata(world.registryAccess());access.setUpgrade(dan200.computercraft.api.turtle.TurtleSide.LEFT,null);access.getInventory().clearContent();access.setFuelLevel(0);turtle.loadWithComponents(saved,world.registryAccess());
   if(!(turtle.getAccess().getUpgrade(dan200.computercraft.api.turtle.TurtleSide.LEFT) instanceof FumeTool)||turtle.getAccess().getFuelLevel()!=37||turtle.getAccess().getInventory().getItem(0).getCount()!=3)throw new IllegalStateException("Fume native upgrade/fuel/inventory reload");
   System.out.println("TT FUME TOOL AUDIT: ALL PASS (loaded upgrade,native turtle,install,attack failure,dig bounds,three gases,ordinary block retained,fuel/inventory conservation,empty success,upgrade/fuel/inventory reload)");
  }finally{if(turtle!=null)turtle.getAccess().getInventory().clearContent();backup.forEach((p,state)->world.setBlock(p,state,3));}
 }
}
